    ["<HyperLink stylename=\"Chat_Name\" u=\"role=%s\">[%s]</>花费了%d俱乐部基金，将%s升级到%d级"] = "<HyperLink stylename=\"Chat_Name\" u=\"role=%s\"> [%s] </> потратил %d клубных средств на повышение %s до уровня %d.",
